    "codigo": "// notificationService.js
const MAX_RETRIES = 3;

async function sendNotification(type, params) {
  const startTime = Date.now();
  let lastError;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    console.log(`[${type}] Tentativa ${attempt}/${MAX_RETRIES} — iniciando envio`);
    try {
      if (type === 'Email') {
        const { to, subject, body } = params;
        await emailApi.send({ to, subject, body });
      } else if (type === 'SMS') {
        const { phoneNumber, text } = params;
        await smsApi.send({ phoneNumber, text });
      } else if (type === 'Push') {
        const { deviceToken, title, message } = params;
        await pushApi.send({ deviceToken, title, message });
      }
      const elapsed = Date.now() - startTime;
      console.log(`[${type}] Sucesso após ${elapsed}ms`);
      return;
    } catch (err) {
      lastError = err;
      console.error(`[${type}] Falha na tentativa ${attempt}: ${err.message}`);
    }
  }

  throw lastError;
}

async function sendEmail(to, subject, body) {
  await sendNotification('Email', { to, subject, body });
}

async function sendSms(phoneNumber, text) {
  await sendNotification('SMS', { phoneNumber, text });
}

async function sendPushNotification(deviceToken, title, message) {
  await sendNotification('Push', { deviceToken, title, message });
}

module.exports = { sendEmail, sendSms, sendPushNotification };
